def _ua_master_remove_class_divs(source, class_names):
    terms = "|".join(re.escape(value) for value in class_names)
    pattern = re.compile(
        r'<div\b[^>]*\bclass=["\'][^"\']*\b(?:' + terms
        + r')\b[^"\']*["\'][^>]*>',
        re.IGNORECASE,
