        ("Автомобіль у Києві та готовий до огляду.", ""),
        ("После внесения предоплаты 500 $ автомобиль прибудет в Киев в течение "
         "15 календарных дней. Точная дата появится после внесения предоплаты.",
         "До Киева — до 15 календарных дней после бронирования за 500 $. "
         "Точную дату укажем после отправки."),
        ("Після внесення передоплати 500 $ автомобіль прибуде до Києва протягом "
         "15 календарних днів. Точна дата з’явиться після внесення передоплати.",
         "До Києва — до 15 календарних днів після бронювання за 500 $. "
         "Точну дату вкажемо після відправлення."),
        ("После внесения предоплаты 500 $ автомобиль будет отправлен ближайшим "
         "паромом. Дата прибытия будет рассчитана после погрузки на паром.",
         "Предоплата 500 $ фиксирует бронирование. Отправка — ближайшим рейсом; "
         "дату прибытия рассчитаем после погрузки."),
        ("Після внесення передоплати 500 $ автомобіль буде відправлено найближчим "
         "поромом. Дату прибуття буде розраховано після завантаження на пором.",
         "Передоплата 500 $ фіксує бронювання. Відправлення — найближчим рейсом; "
         "дату прибуття розрахуємо після завантаження."),
    )
    for old, new in replacements:
        block = block.replace(old, new)

    spec = _ua083_re.search(
        r'<div class=["\']ua-cat-vin-v1-spec["\']>\s*'
        r'Двигатель:\s*<b>(.*?)</b>\s*·\s*Видео:\s*<b>(\d+)</b>\s*</div>',
        block, _ua083_re.I | _ua083_re.S,
    )
    if spec:
        engine_html, video_text = spec.group(1), spec.group(2)
        engine_text = _ua083_visible(engine_html)
        upper_text = _ua083_visible(upper)
        video_duplicate = bool(_ua083_re.search(
            r'(^|\D)' + _ua083_re.escape(video_text) +
            r'\s*(?:видео|відео)(?:\D|$)', upper_text,
        ))
        pieces = []
        if engine_text and engine_text not in upper_text:
            pieces.append("Двигатель: <b>" + engine_html + "</b>")
        if int(video_text) > 0 and not video_duplicate:
            pieces.append("Видео: <b>" + video_text + "</b>")
        replacement = (
            '<div class="ua-cat-vin-v1-spec">' + " · ".join(pieces) + "</div>"
            if pieces else ""
        )
        block = block[:spec.start()] + replacement + block[spec.end():]

    copy = _ua083_re.search(
        r'<div class=["\']ua-cat-vin-v1-copy["\']>(.*?)</div>',
        block, _ua083_re.I | _ua083_re.S,
    )
    if copy and not _ua083_visible(copy.group(1)):
        block = block[:copy.start()] + block[copy.end():]
    block = _ua083_re.sub(r"([.!?])\s{2,}", r"\1 ", block)
    return block

def _ua083_dedup_catalog(source):
    pattern = _ua083_re.compile(
        _ua083_re.escape(_UA083_CAT_START) + r".*?" +
        _ua083_re.escape(_UA083_CAT_END), _ua083_re.S,
    )
    matches = list(pattern.finditer(source))
    if not matches:
        return source
    output = []
    cursor = 0
    previous_end = 0
    for match in matches:
        output.append(source[cursor:match.start()])
        upper = source[previous_end:match.start()]
        output.append(_ua083_dedup_block(match.group(0), upper))
        cursor = match.end()
        previous_end = match.end()
    output.append(source[cursor:])
    return "".join(output)

def _ua068_ensure_catalog_base(source, rows):
    if not source:
        return source
    rows = {str(k).upper(): dict(v or {}) for k, v in (rows or {}).items()}
    source = _ua068_terms(source)
    source = _ua068_cache_meta(source)
    source = _ua068_replace_marked(source, _UA068_FALLBACK_START, _UA068_FALLBACK_END)
    source = _ua068_replace_marked(source, _UA068_CAT_START, _UA068_CAT_END)
    # Catalogs currently exist in two layouts: modern <article> cards and
    # legacy standalone <a> tiles.  A page may also contain both layouts
    # (or a second link to one car).  Insert exactly one canonical block per
    # identifier instead of choosing one page-wide parser branch.
    seen = set()

    def render_once(match):
        block = match.group(0)
        found = _ua068_re.search(r"UA-[0-9]{4,}", block, _ua068_re.I)
        if not found:
            return _ua068_terms(block)
        identifier = found.group(0).upper()
        if identifier not in rows or identifier in seen:
            return _ua068_terms(block)
        rendered = _ua068_catalog_item(block, rows)
        if 'data-ua-card="%s"' % identifier in rendered:
            seen.add(identifier)
        return rendered

    article = _ua068_re.compile(
        r'<article\b[^>]*>.*?</article\s*>', _ua068_re.I | _ua068_re.S)
    source = article.sub(render_once, source)
    anchor = _ua068_re.compile(
        r'<a\b(?=[^>]*href=["\'][^"\']*UA-[0-9]{4,}\.html(?:\?[^"\']*)?["\'])[^>]*>.*?</a\s*>',
        _ua068_re.I | _ua068_re.S)
    source = anchor.sub(render_once, source)

    missing = [identifier for identifier in rows if identifier not in seen]
    if missing:
        fallback = "".join(_ua068_catalog_fallback(identifier, rows[identifier])
                           for identifier in missing)
        position = -1
        modern = _ua068_re.search(r'<div\b[^>]*class=["\'][^"\']*\bempty-assist\b',
                                  source, _ua068_re.I)
        if modern:
            position = modern.start()
        if position < 0:
            legacy = _ua068_re.search(
                r'<a\b(?=[^>]*class=["\'][^"\']*\bvtoraya\b)(?=[^>]*href=["\'][^"\']*podbor\.html)',
                source, _ua068_re.I)
            if legacy:
                position = legacy.start()
        if position < 0:
            position = source.lower().rfind("</main>")
        if position < 0:
            position = source.lower().rfind("</body>")
        if position < 0:
            raise RuntimeError("UA068_CATALOG_INSERTION_POINT_MISSING")
        source = source[:position] + fallback + source[position:]
        seen.update(missing)

    total = len(rows)
    source = _ua068_re.sub(
        r'(<div\b[^>]*class=["\']schet["\'][^>]*>)\s*\d+\s+в подборке',
        lambda match: match.group(1) + str(total) + " в подборке", source,
        flags=_ua068_re.I)
    counts = {stage: sum(1 for row in rows.values() if _ua068_stage(row) == stage)
              for stage in (1, 2, 3, 4)}
    count_labels = (
        (r"Все\s*·\s*\d+", "Все · %d" % total),
        (r"Усі\s*·\s*\d+", "Усі · %d" % total),
        (r"В Киеве\s*·\s*\d+", "В Киеве · %d" % counts[4]),
        (r"У Києві\s*·\s*\d+", "У Києві · %d" % counts[4]),
        (r"В Грузии\s*·\s*\d+", "В Грузии · %d" % counts[3]),
        (r"У Грузії\s*·\s*\d+", "У Грузії · %d" % counts[3]),
        (r"На пароме\s*·\s*\d+", "На пароме · %d" % counts[2]),
        (r"На поромі\s*·\s*\d+", "На поромі · %d" % counts[2]),
        (r"В Корее\s*·\s*\d+", "В Корее · %d" % counts[1]),
        (r"У Кореї\s*·\s*\d+", "У Кореї · %d" % counts[1]),
        (r"Показано:\s*\d+", "Показано: %d" % total),
    )
    for pattern, replacement in count_labels:
        source = _ua068_re.sub(pattern, replacement, source, flags=_ua068_re.I)
    source = _ua068_re.sub(
        r'href=(["\'])([^"\']*UA-[0-9]{4,}\.html)(?:\?[^"\']*)?\1',
        lambda match: 'href=%s%s?v=%s%s' % (match.group(1), match.group(2), _UA068_VERSION, match.group(1)),
        source, flags=_ua068_re.I)
    css = """<style id="ua-cat-vin-v1-style">.ua-cat-vin-v1{margin:12px 0 2px;padding:11px 12px;border-radius:13px;background:linear-gradient(145deg,rgba(240,166,60,.10),rgba(20,36,55,.72));border:1px solid rgba(240,166,60,.32);color:#cbd8e6;font-size:12px;line-height:1.42}.ua-cat-vin-v1-top{display:flex;align-items:center;gap:8px}.ua-cat-vin-v1-top span{min-width:0;overflow-wrap:anywhere}.ua-cat-vin-v1-top b{font:800 11px/1.2 ui-monospace,SFMono-Regular,Menlo,monospace;color:#f3f6fa;letter-spacing:.03em}.ua-cat-vin-v1-top i{margin-left:auto;font-style:normal;font-size:8px;font-weight:900;letter-spacing:.06em;padding:4px 6px;border-radius:999px;white-space:nowrap}.ua-cat-vin-v1-top i.ok{color:#72dfa5;border:1px solid rgba(64,190,125,.42)}.ua-cat-vin-v1-top i.warn{color:#ffd180;border:1px solid rgba(240,166,60,.45)}.ua-cat-vin-v1-top i.error{color:#ff9898;border:1px solid rgba(235,80,80,.4)}.ua-cat-vin-v1-spec{margin-top:5px;color:#aabbd0}.ua-cat-vin-v1-copy{margin-top:5px;color:#aabbd0}.ua-cat-fallback-v1{display:block;margin:14px 0;padding:17px;border:1px solid rgba(240,166,60,.46);border-radius:18px;background:linear-gradient(145deg,#172a40,#102033);color:#edf3fb;text-decoration:none;box-shadow:0 12px 30px rgba(0,0,0,.2)}.ua-cat-fallback-v1-kicker{display:block;color:#f0a63c;font-size:10px;font-weight:900;letter-spacing:.11em}.ua-cat-fallback-v1-title{display:block;margin-top:7px;font-size:20px;line-height:1.25}.ua-cat-fallback-v1-stage{display:block;margin-top:7px;color:#aebed0;font-size:13px}.ua-cat-fallback-v1-open{display:block;margin-top:11px;color:#f4b65c;font-size:13px;font-weight:850}.ua068-uk{display:none}html:lang(uk) .ua068-ru{display:none}html:lang(uk) .ua068-uk{display:inline}/* UA-CATALOG-CARD-UNIFY-002-V1.0 */.catalog-card{--ua-card-surface:#0f2137;overflow:hidden!important;}.catalog-card .catalog-body{background:var(--ua-card-surface)!important;border-radius:0!important;margin-bottom:0!important;}.catalog-card .ua-cat-vin-v1{margin:0!important;padding:14px 20px 18px!important;border:0!important;border-top:1px solid rgba(240,166,60,.32)!important;border-radius:0 0 20px 20px!important;background:var(--ua-card-surface)!important;box-shadow:none!important;}@media(max-width:520px){.catalog-card .ua-cat-vin-v1{padding:13px 20px 17px!important;}}</style>"""
    source = _ua068_re.sub(r'<style\b[^>]*id=["\']ua-cat-vin-v1-style["\'][^>]*>.*?</style\s*>', "", source,
                           flags=_ua068_re.I | _ua068_re.S)
    head_end = source.lower().find("</head>")
    if head_end >= 0:
        source = source[:head_end] + css + source[head_end:]
    return _ua068_terms(source)



def _ua068_ensure_catalog(*args, **kwargs):
    return _ua083_dedup_catalog(_ua068_ensure_catalog_base(*args, **kwargs))

def _ua068_card_errors(source, kod, row):
    errors = []
    if _ua068_re.search(
            r"carhistory(?:\.kr)?|проверить\s+vin|перевірити\s+vin|2\s*200\s*krw",
            source, _ua068_re.I):
        errors.append("VIN advertisement forbidden")
    if source.count(_UA068_VIN_START) != 1 or source.count(_UA068_VIN_END) != 1:
        errors.append("VIN Guard blocks != 1")
    errors.extend(_ua068_primary_action_errors(source, kod, row))
    if source.count(_UA068_STAGE_START) != 1 or source.count(_UA068_STAGE_END) != 1:
        errors.append("stage anchors != 1")
    if source.count(_UA068_DIAG) != 1:
        errors.append("diagnostics anchors != 1")
    diag_links = _ua068_re.findall(
        r'href=["\'](?:[^"\']*/)?' + _ua068_re.escape(str(kod)) + r'-diag\.html(?:\?[^"\']*)?["\']',
        source, _ua068_re.I)
    if len(diag_links) != 1:
        errors.append("diagnostics links != 1")
    if _ua068_forbidden_count(source):
        errors.append("forbidden sea wording remains")
    if _ua068_re.search(
            r'class=["\'][^"\']*\b(?:mcf-etap|mcf-track|mcf-diag-off)\b[^"\']*["\']',
            source, _ua068_re.I):
        errors.append("legacy duplicate UI remains")
    if _ua068_native_stage_span(source) is not None:
        errors.append("native stage duplicate remains")
    vin = str((row or {}).get("vin") or "").strip().upper()
    if not vin or vin not in source:
        errors.append("VIN missing")
    engine = _ua068_engine(row)
    if engine and not _ua068_re.search(_ua068_re.escape(engine) + r"\s*см³", source):
        errors.append("engine mismatch")
    stage = _ua068_stage(row)
    if 'data-ua-stage="%d"' % stage not in source:
        errors.append("stage copy mismatch")
    if stage == 4 and ("Выдача и осмотр — Киев" in source or "Видача та огляд — Київ" in source):
        errors.append("redundant Kyiv issue/inspection copy remains")
    expected_videos = _ua068_video_count(kod, row, source)
    if 'data-ua-video-count="%d"' % expected_videos not in source:
        errors.append("video count mismatch")
    return errors

_ua068_master_card_original = obrabotat_kartochku
_ua068_master_validate_original = proverit
_ua068_master_common_original = obrabotat_obshuyu


def _ua068_master_row(kod):
    row = dict(dannye(kod) or {})
    row.setdefault("auto_number", kod)
    vin = str(row.get("vin") or "").strip().upper()
    duplicate_count = 0
    try:
        for other_kod in vse_kody():
            other = dict(dannye(other_kod) or {})
            if str(other.get("vin") or "").strip().upper() == vin:
                duplicate_count += 1
    except Exception:
        duplicate_count = 1
    row["_ua068_vin_duplicates"] = max(1, duplicate_count)
    return row


def obrabotat_kartochku(html, kod):
    html = _ua068_master_card_original(html, kod)
    if not html:
        return html
    kod = str(kod)
    row = _ua068_master_row(kod)
    html = _ua068_ensure_card(html, kod, row)
    _ua068_ensure_diag_files(kod, row)
    errors = _ua068_card_errors(html, kod, row)
    if errors:
        raise RuntimeError("UA068_MASTER_FINAL:%s:%s" % (kod, ";".join(errors)))
    return html


def proverit(html, kod=""):
    errors = list(_ua068_master_validate_original(html, kod) or [])
    if kod:
        errors.extend(_ua068_card_errors(html, str(kod), _ua068_master_row(str(kod))))
    return list(dict.fromkeys(errors))


def obrabotat_obshuyu(html):
    html = _ua068_master_common_original(html)
    rows = {}
    try:
        for kod in vse_kody():
            row = _ua068_master_row(str(kod))
            if int(row.get("published") or 0) != 1:
                continue
            rows[str(kod).upper()] = row
    except Exception:
        pass
    return _ua068_ensure_catalog(html, rows)
# CATALOG-DESIGN-STAGE-RESTORE-090-V1.0:MASTER:START
def obrabotat_obshuyu(html):
    from ua_delivery_status import stage_number
    import pathlib as _ua090_pathlib
    import catalog_design_guard as _ua090_design

    _rows = {}
    for _kod in vse_kody():
        _row = dict(_ua068_master_row(str(_kod)) or {})
        try:
            _published = int(_row.get("published") or 0)
        except (TypeError, ValueError):
            _published = 0
        if _published != 1 or not stage_number(_row.get("status")):
            continue
        _identifier = str(_kod).strip().upper()
        _rows[_identifier] = _row

    _photos = {}
    for _identifier in sorted(_rows):
        _primary = _ua090_pathlib.Path("/home/Carix/video") / (_identifier + ".html")
        if not _primary.is_file():
            raise RuntimeError("TASK090_PRIMARY_MISSING:" + _identifier)
        _page = _primary.read_text(encoding="utf-8", errors="replace")
        _photos[_identifier] = _ua090_design.extract_main_photo(_page, _identifier)

    _result = _ua090_design.build_from_golden_path(_rows.values(), _photos)
    _audit = _ua090_design.audit_catalog(
        _result, _rows.values(),
        _ua090_design.GOLDEN_PATH.read_text(encoding="utf-8"),
    )
    if _audit.get("status") != "PASS":
        raise RuntimeError("TASK090_CATALOG_AUDIT:" + ",".join(_audit.get("errors") or []))
    return _result
# CATALOG-DESIGN-STAGE-RESTORE-090-V1.0:MASTER:END

# >>> UA099 ADDITIONAL SPEC MASTER V1
_UA099_BASE_OBRABOTAT_KARTOCHKU = obrabotat_kartochku
_UA099_BASE_OBRABOTAT_DIAGNOSTIKU = obrabotat_diagnostiku
_UA099_BASE_PROVERIT = proverit

_UA099_OBSOLETE_VIN_ERRORS = {
    "VIN Guard blocks != 1",
    "VIN buttons != 1",
    "CarHistory target != 1",
    "VIN copy helper missing",
    "video count mismatch",
    "SEO068 CTA",
}

def obrabotat_kartochku(html, kod):
    html = _UA099_BASE_OBRABOTAT_KARTOCHKU(html, kod)
    if not html:
        return html
    import ua_additional_spec as _ua099_spec
