# -*- coding: utf-8 -*-
# UA-V58 · UA-V75 · клиентские страницы · ведёт клиентская линия
# Правки этого файла согласовывать: внутри живут «Купить авто», техсостояние
# из condition_text, фото и видео в каталоге, кнопки связи и «Чат online».
# stranica.py — ОДИН ФАЙЛ. СОБИРАЕТ СТРАНИЦУ ПОКУПАТЕЛЯ И КАТАЛОГ.
#
# Ничего не перехватывает, не подключается в usercustomize, не работает в фоне.
# Запустил "Run this file" — страницы пересобраны, ссылки напечатаны. Всё.
#
# Данные: crm.db. Фото: уже скачанные кадры в /home/Carix/video/foto/UA-XXXX/,
# если их нет — достаются из ранее собранных страниц.

import os, io, re, json, glob, time, base64, sqlite3, traceback

BAZA_DIR  = "/home/Carix"
VALYUTA   = "USD"
TELEFON   = "[N]"
ADRES     = "ул. Победы 20, Киев"
WHATSAPP  = "[N]"
BRON_USD  = 500
SROK_DNEY = 15

PAPKA_VID  = os.path.join(BAZA_DIR, "video")


# UA-V88 · заставка из самого ролика
def zastavka(otn):
    """Возвращает poster='...', если рядом с роликом лежит его первый кадр."""
    try:
        put = os.path.join(PAPKA_VID, otn + ".poster.jpg")
        if os.path.exists(put) and os.path.getsize(put) > 1000:
            return " poster='%s.poster.jpg'" % otn
    except Exception:
        pass
    return ""


PAPKA_SITE = os.path.join(BAZA_DIR, "site")
PAPKA_FOTO = os.path.join(PAPKA_VID, "foto")


def chitat(put, limit=6_000_000):
    with io.open(put, "r", encoding="utf-8", errors="ignore") as f:
        return f.read(limit)


def fajl(imya, inache=""):
    try:
        return chitat(os.path.join(BAZA_DIR, imya), 4000).strip()
    except Exception:
        return inache


def ekran(s):
    return str(s or "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


def sajt():
    adres = fajl("video_sayt.txt")
    if adres:
        return adres.rstrip("/")
    return "[URL]" % os.path.basename(BAZA_DIR.rstrip("/")).lower()


def karta_url():
    return fajl("karta_ssylka.txt", "[URL]")


def imya_bota():
    est = fajl("bot_imya.txt")
    if est:
        return est
    try:
        import urllib.request
        tok = fajl("bot_token.txt")
        with urllib.request.urlopen("[URL]" % tok, timeout=15) as r:
            d = json.loads(r.read().decode("utf-8"))
        imya = (d.get("result") or {}).get("username") or ""
        if imya:
            with io.open(os.path.join(BAZA_DIR, "bot_imya.txt"), "w", encoding="utf-8") as f:
                f.write(imya)
        return imya
    except Exception:
        return ""


def v_bota(chto):
    imya = imya_bota()
    return ("[URL]" % (imya, chto)) if imya else ("[URL]" % WHATSAPP)


# --------------------------------------------------------------------- ДАННЫЕ
def mashiny():
    con = sqlite3.connect("file:%s?mode=ro" % os.path.join(BAZA_DIR, "crm.db"), uri=True)
    con.row_factory = sqlite3.Row
    try:
        return [dict(r) for r in con.execute("SELECT * FROM cars WHERE published=1 ORDER BY id")]
    finally:
        con.close()


def nomer(m):
    return (m.get("auto_number") or "UA-%04d" % int(m.get("id") or 0)).strip()


def cena(m):
    c = m.get("price_uah") or m.get("price_total") or 0
    try:
        c = int(float(c))
    except Exception:
        c = 0
    if not c:
        return "цена по запросу"
    return ("{:,}".format(c).replace(",", " ") + (" $" if VALYUTA == "USD" else " ₴"))


def etap_dlinno(m):
    s = (m.get("status") or "").lower()
    if s.startswith("sold"):
        return "продана · в пути", False
    if s.startswith("kr_"):
        return "Выкуплена · стоянка в Корее", False
    if s.startswith("sea_"):
        return "На пароме · Корея → Грузия", False
    if s == "ge_to_kyiv":
        return "Выехала из Грузии · едет в Киев", True
    if s.startswith("ge_"):
        return "В Грузии · Поти/Батуми, оформление", True
    if s.startswith("ua_"):
        # UA-V75 · машина уже здесь — предоплата не нужна
        return "В Киеве · можно посмотреть", False
    return "В работе", False


def etap_korotko(m):
    s = (m.get("status") or "").lower()
    for nachalo, slovo in (("sold", "продана"), ("kr_", "в Корее"), ("sea_", "на пароме"),
                           ("ge_to_kyiv", "едет в Киев"), ("ge_", "в Грузии"), ("ua_", "в Киеве")):
        if s.startswith(nachalo):
            return slovo
    return "в работе"


def nomer_etapa(m):
    s = (m.get("status") or "").lower()
    if s.startswith("kr_"):
        return 1
    if s.startswith("sea_"):
        return 2
    if s == "ge_to_kyiv":
        return 3
    if s.startswith("ge_"):
        return 3
    if s.startswith("ua_"):
        return 4
    return 1


def sklonenie(n):
    if n % 10 == 1 and n % 100 != 11:
        return "день"
    if n % 10 in (2, 3, 4) and n % 100 not in (12, 13, 14):
        return "дня"
    return "дней"


# ── UA-V115 · остаток дней до Киева и шкала прибытия ─────────────────
# Раскладка: погрузка 10 + море 60 + Поти/Батуми 1 + дорога 14 = 85
OSTATOK_PO_ETAPU = {1: 85, 2: 75, 3: 15, 4: 0}
SHKALA_PO_ETAPU = {1: 4, 2: 12, 3: 82, 4: 100}
MESYACY_V115 = ("января", "февраля", "марта", "апреля", "мая", "июня",
                "июля", "августа", "сентября", "октября", "ноября", "декабря")


def ostatok_dney(m):
    """Сколько дней до Киева. Ручная дата важнее расчёта по этапу."""
    eta = (m.get("eta_manual") or "").strip()
    if eta:
        for obr in ("%Y-%m-%d", "%d.%m.%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                cel = time.mktime(time.strptime(eta[:19], obr))
                return max(int((cel - time.time()) // 86400), 0)
            except Exception:
                continue
    return OSTATOK_PO_ETAPU.get(nomer_etapa(m), 0)


def data_vydachi(dney):
    t = time.localtime(time.time() + dney * 86400)
    return "%d %s %d" % (t.tm_mday, MESYACY_V115[t.tm_mon - 1], t.tm_year)


def blok_pribytiya(m):
    """Счётчик дней, дата выдачи и шкала пути. Шкала есть на всех этапах."""
    etap = nomer_etapa(m)
    dney = ostatok_dney(m)
    proc = SHKALA_PO_ETAPU.get(etap, 100)
    c = []
    if etap >= 4 or dney <= 0:
        proc = 100
        c.append("<div style='margin-top:16px;font-size:19px;font-weight:800;"
                 "color:#f0a63c'>Машина в Киеве</div>")
        c.append("<div style='margin-top:5px;font-size:14px;opacity:.75'>"
                 "Приезжайте на осмотр — Победы 20</div>")
    else:
        c.append("<div style='margin-top:16px;display:flex;align-items:baseline;"
                 "gap:10px'>")
        c.append("<div style='font-size:46px;line-height:1;font-weight:800;"
                 "color:#f0a63c'>%d</div>" % dney)
        c.append("<div style='font-size:15px;font-weight:600'>%s до выдачи"
                 "<br>в Киеве</div>" % sklonenie(dney))
        c.append("</div>")
        c.append("<div style='margin-top:8px;font-size:14px;opacity:.75'>"
                 "Ориентировочная дата выдачи — <b>%s</b></div>"
                 % data_vydachi(dney))
    c.append("<div style='margin-top:16px;height:5px;border-radius:3px;"
             "background:rgba(255,255,255,.10);overflow:hidden'>"
             "<div style='height:100%%;width:%d%%;background:#f0a63c;"
             "border-radius:3px'></div></div>" % proc)
    c.append("<div style='display:flex;justify-content:space-between;"
             "margin-top:8px;font-size:11px;opacity:.65'>")
    for i, nazv in enumerate(("Корея", "Паром", "Грузия", "Киев"), 1):
        stil = "color:#f0a63c;font-weight:700;opacity:1" if i <= etap else ""
        c.append("<span style='%s'>%s</span>" % (stil, nazv))
    c.append("</div></div>")
    return "".join(c)


def srok(m):
    eta = (m.get("eta_manual") or "").strip()
    if eta:
        for obr in ("%Y-%m-%d", "%d.%m.%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                cel = time.mktime(time.strptime(eta[:19], obr))
                ostalos = int((cel - time.time()) // 86400)
                if ostalos > 0:
                    return "До прибытия в Киев — %d %s" % (ostalos, sklonenie(ostalos))
                return "Прибытие в Киев ожидается со дня на день"
            except Exception:
                continue
    s = (m.get("status") or "").lower()
    if s.startswith("ua_"):
        return "Машина в Киеве — можно приехать и посмотреть"
    if s == "ge_to_kyiv":
        try:
            pamyat = json.loads(chitat(os.path.join(BAZA_DIR, ".etapy.json"), 200000))
            kogda = (pamyat.get(nomer(m)) or {}).get("s_kogda")
        except Exception:
            kogda = None
        if kogda:
            ostalos = SROK_DNEY - int((time.time() - kogda) // 86400)
            if ostalos > 0:
                return "До прибытия в Киев — %d %s" % (ostalos, sklonenie(ostalos))
            return "Прибытие в Киев ожидается со дня на день"
    d = ostatok_dney(m)  # UA-V115
    return "До Киева — %d %s" % (d, sklonenie(d))
# ----------------------------------------------------------------------- ФОТО
def razmer_jpeg(put):
    try:
        with open(put, "rb") as f:
            d = f.read(200000)
    except Exception:
        return (0, 0)
    i = 2
    while i < len(d) - 9:
        if d[i] != 0xFF:
            i += 1
            continue
        marker = d[i + 1]
        if marker in (0xC0, 0xC1, 0xC2, 0xC3, 0xC5, 0xC6, 0xC7, 0xC9, 0xCA, 0xCB, 0xCD, 0xCE, 0xCF):
            return ((d[i + 7] << 8) + d[i + 8], (d[i + 5] << 8) + d[i + 6])
        if marker in (0xD8, 0xD9) or 0xD0 <= marker <= 0xD7:
            i += 2
            continue
        i += 2 + (d[i + 2] << 8) + d[i + 3]
    return (0, 0)


SREDNIJ = 1000   # для ленты в карточке и главной плитки каталога
MALYJ   = 440    # для мини-ленты и обложки главной


def variant(otn, papka):
    """foto/UA-0001/003.jpg → foto/UA-0001/m/003.jpg"""
    chasti = otn.rsplit("/", 1)
    return "%s/%s/%s" % (chasti[0], papka, chasti[1])


def umenshit(otn, papka, shirina, kachestvo):
    """Делает уменьшенную копию кадра. Возвращает путь для страницы."""
    ishod = os.path.join(PAPKA_VID, otn)
    cel_otn = variant(otn, papka)
    cel = os.path.join(PAPKA_VID, cel_otn)
    try:
        if (os.path.exists(cel) and os.path.getsize(cel) > 1000
                and os.path.getmtime(cel) >= os.path.getmtime(ishod)):
            return cel_otn
    except Exception:
        pass
    try:
        from PIL import Image
    except Exception:
        return otn
    try:
        im = Image.open(ishod)
        if im.mode not in ("RGB", "L"):
            im = im.convert("RGB")
        if im.width > shirina:
            im = im.resize((shirina, max(int(im.height * shirina / im.width), 1)),
                           Image.LANCZOS)
        os.makedirs(os.path.dirname(cel), exist_ok=True)
        im.save(cel, "JPEG", quality=kachestvo, optimize=True, progressive=True)
        return cel_otn
    except Exception:
        return otn


def legkie(puti):
    """Готовит облегчённые версии всех кадров машины."""
    sredn, mal = [], []
    for otn in puti:
        sredn.append(umenshit(otn, "m", SREDNIJ, 78))
        mal.append(umenshit(otn, "s", MALYJ, 72))
    return sredn, mal


def ves(puti):
    itog = 0
    for otn in puti:
        try:
            itog += os.path.getsize(os.path.join(PAPKA_VID, otn))
        except Exception:
            pass
    return itog


def dostat_iz_stranic(nom, papka):
    """Запасной источник: кадры, вшитые в ранее собранные страницы."""
    kandidaty = []
    for shablon in (os.path.join(PAPKA_VID, nom + "*.html"),
                    os.path.join(PAPKA_SITE, nom + "*.html"),
                    os.path.join(BAZA_DIR, "staroe", "**", nom + "*.html")):
        kandidaty += glob.glob(shablon, recursive=True)
    kadry = []
    for put in kandidaty:
        try:
            najdeno = re.findall(
                r"data:image/(?:jpeg|jpg|png);base64,([A-Za-z0-9+/=]{2000,})", chitat(put))
        except Exception:
            continue
        if len(najdeno) > len(kadry):
            kadry = najdeno
    for i, kusok in enumerate(kadry, 1):
        put = os.path.join(papka, "%03d.jpg" % i)
        try:
            if not os.path.exists(put) or os.path.getsize(put) < 1000:
                with open(put, "wb") as f:
                    f.write(base64.b64decode(kusok + "=" * (-len(kusok) % 4)))
        except Exception:
            continue
    return len(kadry)


def kadry_mashiny(m):
    nom = nomer(m)
    papka = os.path.join(PAPKA_FOTO, nom)
    os.makedirs(papka, exist_ok=True)
    est = sorted(glob.glob(os.path.join(papka, "*.jpg")))
    if not est:
        dostat_iz_stranic(nom, papka)
        est = sorted(glob.glob(os.path.join(papka, "*.jpg")))
    puti = ["foto/%s/%s" % (nom, os.path.basename(x)) for x in est
            if os.path.getsize(x) > 1000]
    from photo_visibility import visible_names
    visible = set(visible_names(m, [os.path.basename(p) for p in puti]))
    puti = [p for p in puti if os.path.basename(p) in visible]
    # первым — первый горизонтальный кадр
    if not m.get("cover_photo"):
        for otn in puti:
            sh, vy = razmer_jpeg(os.path.join(PAPKA_VID, otn))
            if sh and vy and sh / float(vy) >= 1.2:
                if puti[0] != otn:
                    puti = [otn] + [x for x in puti if x != otn]
                break
    return puti


