    def zapisat(put, text, *ostalnye, **imenovannye):
        _ish = _v172_zapisat_ishodnaya
        try:
            imya = os.path.basename(str(put))
            karta = bool(re.match(r"^UA-[A-Za-z0-9\-]+\.html$", imya)) \
                and "-diag" not in imya
            if karta and text:
                propalo = [x for x in V172_OBYAZATELNO if x not in text]
                if propalo and os.path.isfile(put):
                    with io.open(put, "r", encoding="utf-8",
                                 errors="replace") as _f:
                        staraya = _f.read()
                    bylo = [x for x in propalo if x in staraya]
                    if bylo:
                        _v172_zapis_v_zhurnal(
                            "ОТКАЗ · %s · в новой странице пропало: %s · "
                            "рабочая оставлена" % (imya, ", ".join(bylo)))
                        return None
        except Exception:
