def _ua068_native_stage_span(source):
    heading = _ua068_re.search(
        r'<div\b(?=[^>]*\bclass=["\'][^"\']*\bzag\b[^"\']*["\'])[^>]*>\s*'
        r'(?:Где\s+(?:машина|автомобиль)\s+сейчас|'
