        position = source.find(_UA068_STAGE_END)
        if position >= 0:
            position += len(_UA068_STAGE_END)
        else:
            position = source.lower().rfind("</body>")
        source = source[:position] + _ua068_diag_anchor(kod) + source[position:]
    return _ua068_strip_legacy_blocks(source)


